133	  }
134	  .divider {
135	    @apply my-4 border-t border-white/[0.06];
136	  }
137	  .skeleton {
138	    @apply animate-pulse rounded-lg bg-white/[0.06];
139	  }
140	
141	  /* ── Marketing design system (v2 redesign) ─────────────────────────────────
142	     Shared primitives so every page reads as one designed site. The Section
143	     component alternates these background "tones" to give the long pages rhythm
144	     instead of a flat stack. Colors/animations are the existing brand system. */
145	
146	  /* Eyebrow label above section/hero headings (the ubiquitous uppercase tag). */
147	  .eyebrow {
148	    @apply inline-flex items-center gap-2 text-[12px] font-semibold uppercase tracking-[0.16em] text-brand-300;
149	  }
150	  .eyebrow-pill {
151	    @apply inline-flex items-center gap-2 rounded-full border border-brand-500/20 bg-brand-500/[0.08] px-3 py-1 text-[11px] font-semibold uppercase tracking-[0.14em] text-brand-200;
152	  }
153	
154	  /* Section background tones for alternating rhythm. "panel" is a hair lighter
155	     than the page with hairline separators; "deep" recedes. Replaces one-off
156	     inline gradients scattered across pages. */
157	  .tone-panel {
158	    @apply border-y border-white/[0.05] bg-navy-900/40;
159	  }
160	  .tone-deep {
161	    background: linear-gradient(180deg, rgb(6 10 20 / 0) 0%, rgb(8 12 24 / 0.6) 50%, rgb(6 10 20 / 0) 100%);
162	  }
163	
164	  /* Foreground tokens so tone-aware primitives (SectionTitle, FeatureCard) flip
165	     text automatically. Default = the dark theme's light text. */
166	  :root {
167	    --fg: #ffffff;
168	    --fg-muted: #94a3b8; /* slate-400 */
169	  }
170	
171	  /* "light" tone — a rare, deliberate light band to break up the dark theme and
172	     divide long pages (used sparingly, ~one per page). Flips the foreground
173	     tokens to dark and restyles surfaces/buttons inside so everything stays
174	     legible without touching each call site. */
175	  .tone-light {
176	    @apply border-y border-slate-200/70 text-slate-700;
177	    background: linear-gradient(180deg, #f4f3fb 0%, #ebe9f5 100%);
178	    --fg: #0f172a;       /* slate-900 */
179	    --fg-muted: #475569; /* slate-600 */
180	  }
181	  .tone-light .card {
182	    @apply border-slate-200 bg-white text-slate-700;
183	    box-shadow: 0 1px 2px rgb(15 23 42 / 0.05), 0 16px 36px -20px rgb(15 23 42 / 0.22);
184	  }
185	  .tone-light .card-hover:hover {
186	    @apply border-brand-500/40 bg-white;
187	  }
188	  .tone-light .glass {
189	    @apply border-slate-200 bg-white/70;
190	  }
191	  .tone-light .section-label {
192	    @apply text-slate-500;
193	  }
194	  .tone-light .btn-secondary {
195	    @apply border-slate-300 bg-white text-slate-800 hover:border-slate-400 hover:bg-slate-50;
196	  }
197	  .tone-light .btn-ghost {
198	    @apply text-slate-600 hover:bg-slate-900/[0.06] hover:text-slate-900;
199	  }
200	
201	  /* Reusable hero aura — the dual-radial violet/blue glow that ~10 sub-page
202	     heroes previously inlined by hand. Sits in an absolutely-positioned layer. */
203	  .hero-aura {
204	    background-image:
205	      radial-gradient(ellipse 70% 60% at 15% 0%, rgb(111 71 245 / 0.20), transparent 70%),
206	      radial-gradient(ellipse 60% 50% at 90% 10%, rgb(59 130 246 / 0.14), transparent 70%);
207	  }
208	
209	  /* Soft violet lift on hover for interactive cards (was inline arbitrary shadow). */
210	  .lift {
211	    @apply transition-all duration-200 hover:-translate-y-0.5 hover:border-brand-500/30;
212	    &:hover { box-shadow: 0 18px 40px -20px rgb(111 71 245 / 0.45); }
213	  }
214	
215	  /* Consistent max-width content rail. */
216	  .rail {
217	    @apply mx-auto max-w-6xl px-5 sm:px-6;
218	  }
219	
220	  /* Top-nav dropdown trigger button. */
221	  .nav-trigger {
222	    @apply inline-flex cursor-pointer items-center gap-1 rounded-lg px-3 py-2 text-sm font-medium text-slate-400 transition-colors hover:text-white;
223	  }
224	  .nav-trigger.is-open {
225	    @apply text-white;
226	  }
227	}
