import Link from "next/link";
import type { Metadata } from "next";
import { Section, SectionTitle, PageHero } from "@/components/marketing/primitives";
import { FeatureCard, CtaBand } from "@/components/marketing/sections";
import { Reveal } from "@/components/marketing/Reveal";
import {
  IconServer,
  IconCode,
  IconDisk,
  IconGlobe,
  IconShield,
  IconLock,
  IconGauge,
  IconSupport,
  IconGift,
  IconCheck,
  IconArrow,
} from "@/components/marketing/icons";

export const metadata: Metadata = {
  title: "Free VPS Migration — Nxeon",
  description:
    "Switch to Nxeon for free — a guided wizard migrates your files, codebase, and databases from your old VPS with live progress, then walks you through the rest. Prefer we handle it? Our team will.",
};

/** The end-to-end path a migration takes, shown as a numbered treatment. */
const STEPS = [
  {
    title: "Connect your old server",
    body: "Point the wizard at your current VPS with its SSH details. We use those credentials transiently to read your data — nothing is stored after the migration.",
  },
  {
    title: "Pick what to move",
    body: "Choose the file paths and databases you want brought over. Migrate a whole app or just the parts that matter — you stay in control of the scope.",
  },
  {
    title: "We copy files + databases",
    body: "The wizard streams your files, codebase, and databases onto your new Nxeon server with live progress, so you can watch each part complete in real time.",
  },
  {
    title: "Point your DNS",
    body: "Verify everything looks right, then switch your domain over. Your old server keeps running until you're ready to cut across, so there's no risky big-bang moment.",
  },
];

/** What is automated vs. what we guide you through — kept deliberately honest. */
const MIGRATE = [
  {
    icon: <IconCode />,
    title: "Files & codebase",
    body: "Your application code, uploads, and site files are copied automatically from the paths you select — preserving the directory structure you already have.",
  },
  {
    icon: <IconDisk />,
    title: "Databases",
    body: "MySQL and PostgreSQL databases are dumped from your source and restored on your new server automatically, so your data lands ready to use.",
  },
  {
    icon: <IconServer />,
    title: "The rest, with a guided checklist",
    body: "Web-server configs, system services, and cron jobs aren't cloned blindly. Instead we hand you a clear, step-by-step checklist to recreate them correctly — or let our team do it for you.",
  },
];

/** The reasons switching is genuinely low-friction. */
const PAINLESS = [
  {
    icon: <IconGift />,
    title: "Free, always",
    body: "Migration is included at no charge. There's no per-gigabyte fee and no upsell — you only pay for the Nxeon server you keep running afterward.",
  },
  {
    icon: <IconGauge />,
    title: "Live progress",
    body: "Watch each file path and database move in real time from your dashboard. No black-box scripts — you can see exactly what has transferred and what's left.",
  },
  {
    icon: <IconLock />,
    title: "Credentials used transiently",
    body: "Your source server's SSH credentials are used only for the duration of the transfer, over an encrypted connection, and are never stored after it completes.",
  },
  {
    icon: <IconShield />,
    title: "No downtime to prepare",
    body: "Your old server stays live throughout. Migrate, verify on Nxeon, and only flip your DNS once you're happy — so there's no scramble and no data left behind.",
  },
  {
    icon: <IconCheck />,
    title: "You choose the scope",
    body: "Move one app or an entire fleet. Pick the exact paths and databases per run, and repeat the wizard as many times as you need at no cost.",
  },
  {
    icon: <IconSupport />,
    title: "Help when you want it",
    body: "Stuck on a tricky config or an unusual stack? Our team is one message away, and can take the wheel on assisted migration whenever you'd rather not do it yourself.",
  },
];

/** A small migration-progress mock for the hero, built from existing primitives. */
function MigrationVisual() {
  const rows = [
    { label: "/var/www/app", meta: "4.2 GB · files", pct: 100, done: true },
    { label: "app_production", meta: "MySQL · 1.1 GB", pct: 100, done: true },
    { label: "/home/deploy/uploads", meta: "8.7 GB · files", pct: 68, done: false },
    { label: "sessions", meta: "PostgreSQL · queued", pct: 0, done: false },
  ];
  return (
    <div className="glass p-5 sm:p-6">
      <div className="flex items-center gap-3 border-b border-white/[0.06] pb-4">
        <span className="flex h-9 w-9 items-center justify-center rounded-lg bg-gradient-to-br from-accent-blue/30 to-brand-500/30 text-brand-200">
          <IconServer size={18} />
        </span>
        <div>
          <p className="text-sm font-semibold text-white">Migrating to nxeon-sg-01</p>
          <p className="font-mono text-xs text-slate-500">from 203.0.113.24 · SSH</p>
        </div>
        <span className="ml-auto inline-flex items-center gap-1.5 rounded-full bg-emerald-500/15 px-2.5 py-1 text-[11px] font-medium text-emerald-300">
          <span className="h-1.5 w-1.5 rounded-full bg-emerald-400 animate-pulse-dot" />
          In progress
        </span>
      </div>
      <div className="mt-4 space-y-3.5">
        {rows.map((r) => (
          <div key={r.label}>
            <div className="flex items-baseline justify-between text-sm">
              <span className="flex items-center gap-2 font-mono text-xs text-slate-300">
                {r.done ? (
                  <span className="flex h-4 w-4 items-center justify-center rounded-full bg-emerald-500/15 text-emerald-400">
                    <IconCheck size={11} />
                  </span>
                ) : (
                  <span className="h-4 w-4 rounded-full border border-white/15" />
                )}
                {r.label}
              </span>
              <span className="font-mono text-[11px] text-slate-500">{r.meta}</span>
            </div>
            <div className="mt-1.5 h-2 w-full overflow-hidden rounded-full bg-white/[0.06]">
              <div
                className={`h-full rounded-full ${
                  r.done
                    ? "bg-emerald-500/70"
                    : "bg-gradient-to-r from-accent-blue to-brand-500"
                }`}
                style={{ width: `${r.pct}%` }}
              />
            </div>
          </div>
        ))}
      </div>
      <div className="mt-5 grid grid-cols-2 gap-3">
        <div className="rounded-xl border border-white/[0.06] bg-white/[0.02] px-4 py-3">
          <p className="text-xs text-slate-500">Cost</p>
          <p className="mt-0.5 text-sm font-semibold text-white">Free</p>
        </div>
        <div className="rounded-xl border border-white/[0.06] bg-white/[0.02] px-4 py-3">
          <p className="text-xs text-slate-500">Old server</p>
          <p className="mt-0.5 text-sm font-semibold text-white">Still running</p>
        </div>
      </div>
    </div>
  );
}

/** Sample of the guided checklist we hand you for the non-automated parts. */
const CHECKLIST = [
  "Reinstall your web server and restore virtual-host / reverse-proxy configs",
  "Re-issue TLS certificates for your domains",
  "Recreate system services, environment variables, and secrets",
  "Restore cron jobs and scheduled tasks",
  "Update your DNS records and verify the new server responds",
];

export default function MigratePage() {
  return (
    <>
      <PageHero
        eyebrow="Free Migration"
        title="Bring your servers"
        highlight="with you"
        sub="Switching hosts shouldn't mean a weekend of scp and prayer. A guided wizard moves your files, codebase, and databases onto Nxeon automatically — with live progress — and walks you through the rest. It's free, and your old server stays live until you're ready."
        primary={{ label: "Start your migration", href: "/register" }}
        secondary={{ label: "Talk to us", href: "/contact" }}
        visual={<MigrationVisual />}
      />

      {/* How it works — numbered */}
      <Section tone="panel" size="lg">
        <SectionTitle
          eyebrow="How it works"
          title="Four steps from old host to new"
          sub="The migration wizard lives in your dashboard. Connect, choose, copy, and cut over — at your own pace, with nothing hidden."
        />
        <div className="mt-12 grid gap-5 sm:grid-cols-2 lg:grid-cols-4">
          {STEPS.map((s, i) => (
            <Reveal key={s.title} delay={i * 80} className="card lift h-full">
              <span className="flex h-10 w-10 items-center justify-center rounded-xl bg-gradient-to-br from-accent-blue/30 to-brand-500/30 text-lg font-bold text-white ring-1 ring-white/10">
                {i + 1}
              </span>
              <h3 className="mt-4 text-base font-semibold text-white">{s.title}</h3>
              <p className="mt-2 text-sm leading-relaxed text-slate-400">{s.body}</p>
            </Reveal>
          ))}
        </div>
      </Section>

      {/* What we migrate — honest split of automatic vs. guided */}
      <Section size="lg">
        <SectionTitle
          eyebrow="What we migrate"
          title="Files and databases, moved for you"
          sub="We're straight with you about what's automatic and what needs a human touch. Your data comes across on its own; the environment around it, we guide you through."
        />
        <div className="mt-12 grid gap-5 md:grid-cols-3">
          {MIGRATE.map((f, i) => (
            <FeatureCard key={f.title} icon={f.icon} title={f.title} delay={(i % 3) * 60}>
              {f.body}
            </FeatureCard>
          ))}
        </div>
      </Section>

      {/* Why it's painless — deliberate light band */}
      <Section tone="light" size="lg">
        <SectionTitle
          eyebrow="Why it's painless"
          title="Low-risk by design, not by luck"
          sub="Every part of the process is built to keep you in control and keep your data safe — with no cost and no downtime forced on you."
        />
        <div className="mt-12 grid gap-5 sm:grid-cols-2 lg:grid-cols-3">
          {PAINLESS.map((f, i) => (
            <FeatureCard key={f.title} icon={f.icon} title={f.title} delay={(i % 3) * 60}>
              {f.body}
            </FeatureCard>
          ))}
        </div>
      </Section>

      {/* Assisted migration */}
      <Section tone="panel" size="lg">
        <div className="grid items-center gap-12 lg:grid-cols-2">
          <div>
            <SectionTitle
              eyebrow="Assisted migration"
              title="Prefer we handle it? Our team will."
              sub="If your stack is unusual, your configs are gnarly, or you'd simply rather not, hand it to us. We'll do the wizard-driven copy for you and work through the checklist together — so the whole move lands correctly."
              align="left"
            />
            <div className="mt-8 flex flex-wrap gap-3">
              <Link href="/register" className="btn-primary px-5 py-3 text-base">
                Start your migration
                <IconArrow size={16} />
              </Link>
              <Link href="/contact" className="btn-secondary px-5 py-3 text-base">
                Talk to our team
              </Link>
            </div>
          </div>
          <Reveal className="lg:pl-6">
            <div className="card">
              <div className="flex items-center gap-2 text-brand-300">
                <IconCheck size={18} />
                <p className="text-sm font-semibold text-[var(--fg)]">The guided checklist covers</p>
              </div>
              <ul className="mt-4 space-y-3">
                {CHECKLIST.map((item) => (
                  <li key={item} className="flex items-start gap-3 text-sm leading-relaxed text-slate-400">
                    <span className="mt-0.5 flex h-5 w-5 shrink-0 items-center justify-center rounded-full bg-emerald-500/15 text-emerald-400">
                      <IconCheck size={12} />
                    </span>
                    {item}
                  </li>
                ))}
              </ul>
              <p className="mt-5 border-t border-white/[0.06] pt-4 text-xs leading-relaxed text-slate-500">
                Automatic for files and databases. The steps above are yours to run with our
                checklist — or ours to run for you with assisted migration.
              </p>
            </div>
          </Reveal>
        </div>
      </Section>

      {/* CTA */}
      <Section tone="deep" size="lg">
        <CtaBand />
      </Section>
    </>
  );
}

